import{_ as i,o as a,c as e,a0 as o}from"./chunks/framework.BFLrGO6w.js";const f=JSON.parse('{"title":"工作規格 02：進階分析","description":"","frontmatter":{},"headers":[],"relativePath":"workstream-02-advanced-analysis.md","filePath":"workstream-02-advanced-analysis.md"}'),r={name:"workstream-02-advanced-analysis.md"};function t(n,l,d,s,h,c){return a(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="工作規格-02-進階分析" tabindex="-1">工作規格 02：進階分析 <a class="header-anchor" href="#工作規格-02-進階分析" aria-label="Permalink to &quot;工作規格 02：進階分析&quot;">​</a></h1><h2 id="文件狀態" tabindex="-1">文件狀態 <a class="header-anchor" href="#文件狀態" aria-label="Permalink to &quot;文件狀態&quot;">​</a></h2><ul><li>編號：<code>02</code></li><li>名稱：進階分析</li><li>狀態：第一階段與通用／龍騎士分析已部分實作，產品主線仍等待工作規格 01</li><li>目前是否開始實作：是（parserVersion 53 evidence baseline）</li><li>優先級：第二順位</li></ul><p>這份文件定義進階分析的目標、前置條件、工作清單與驗收方式。parserVersion 53 已完成不依賴未校準 FFLogs 指標的 evidence baseline；在「工作規格 01：FFLogs 指標對帳」完成前，它仍不是產品主線，也不能用未校準數字產生職業評分。</p><h2 id="與工作規格-01-的順序" tabindex="-1">與工作規格 01 的順序 <a class="header-anchor" href="#與工作規格-01-的順序" aria-label="Permalink to &quot;與工作規格 01 的順序&quot;">​</a></h2><p>整體開發順序固定如下：</p><ol><li><strong>工作規格 01：FFLogs 指標對帳</strong><ul><li>先完成 Healing：raw healing、effective healing、overheal、absorbs、HPS、rHPS 與 mitigation 口徑。</li><li>Healing 穩定後，對帳 DPS 系列：Damage、DPS、nDPS、aDPS、rDPS，以及 Crit／Direct Hit 等相關欄位。</li><li>公式必須來自 FFLogs 定義、官方技能資料或可重現的逐事件證據，不用報告專用倍率硬調。</li></ul></li><li><strong>工作規格 02：進階分析</strong><ul><li>使用已校準的事件、指標與 metadata，建立死亡回放、成功把比較、團隊技能計畫及操作建議。</li></ul></li></ol><p>工作規格 01 的既有文件：</p><ul><li><code>doc/fflogs-reconciliation.md</code></li><li><code>doc/fflogs-healing-formula-audit.md</code></li><li><code>doc/fflogs-rdps-validation-plan.md</code></li><li><code>doc/fflogs-XDt7a138MhLqNbkx-fight-last-baseline.md</code></li><li><code>doc/formulas-qa.md</code></li></ul><h3 id="工作規格-01-目前卡點" tabindex="-1">工作規格 01 目前卡點 <a class="header-anchor" href="#工作規格-01-目前卡點" aria-label="Permalink to &quot;工作規格 01 目前卡點&quot;">​</a></h3><p>目前 Healing 尚未完成，因此 DPS 系列與本規格仍不得視為產品主線完成；但只陳述可觀測事件、保留證據並在資料不足時降級的基礎分析已開始實作：</p><ul><li>有效治療仍與 FFLogs 有差距。</li><li>建築神之塔的 400 potency 尚未完整重建成實際護盾容量。</li><li>部分多盾、同 server frame HP snapshot 與 mitigation 口徑仍待校準。</li><li>Healing 穩定後，才開始逐欄對帳 Damage、DPS、nDPS、aDPS 與 rDPS。</li></ul><h3 id="工作規格-01-的完成門檻" tabindex="-1">工作規格 01 的完成門檻 <a class="header-anchor" href="#工作規格-01-的完成門檻" aria-label="Permalink to &quot;工作規格 01 的完成門檻&quot;">​</a></h3><ul><li>[ ] Healing 所有主表欄位都有明確公式與 FFLogs 基準。</li><li>[ ] 有效治療、overheal、absorbs 的剩餘差異都有逐事件解釋。</li><li>[ ] DPS 系列各指標已有獨立定義，不混用 Damage、DPS、nDPS、aDPS、rDPS。</li><li>[ ] 至少建立多場、不同職業組成的 FFLogs regression baseline。</li><li>[ ] <code>npm run compare:fflogs</code> 能清楚區分已通過、允許誤差與尚未支援的欄位。</li><li>[ ] 程式、<code>doc/formulas-qa.md</code>、設定文件與 parserVersion 保持一致。</li></ul><h2 id="進階分析的產品目標" tabindex="-1">進階分析的產品目標 <a class="header-anchor" href="#進階分析的產品目標" aria-label="Permalink to &quot;進階分析的產品目標&quot;">​</a></h2><p>進階分析要回答的是：</p><blockquote><p>這一把為什麼失敗，與成功把相比差在哪裡，下一把最值得調整什麼？</p></blockquote><p>它不以 FFLogs 排名或模糊總分為目標，也不應只用固定門檻評價玩家。任何結論都必須能回到具體的 log 事件、技能、狀態、時間點與公式。</p><h2 id="核心原則" tabindex="-1">核心原則 <a class="header-anchor" href="#核心原則" aria-label="Permalink to &quot;核心原則&quot;">​</a></h2><ul><li>FFLogs 對帳結果是指標口徑的第一標準。</li><li>使用者指定的成功把是團隊實戰比較的第一基準。</li><li>同一玩家、同一 encounter 的歷史 pull 優先於通用門檻。</li><li>log 直接證據、公式重建與合理推估必須分級顯示。</li><li>證據不足時顯示「無法判定」，不產生肯定式建議。</li><li>所有建議必須附時間點與來源事件，並可跳回 timeline。</li><li>不以單一 overheal、GCD uptime 或 DPS 數字直接判定操作好壞。</li></ul><h2 id="第一階段-可信事件與分析證據" tabindex="-1">第一階段：可信事件與分析證據 <a class="header-anchor" href="#第一階段-可信事件與分析證據" aria-label="Permalink to &quot;第一階段：可信事件與分析證據&quot;">​</a></h2><ul><li>[x] 每項 evidence finding 標示資料來源：log 直接事件／公式重建／合理推估。</li><li>[ ] 顯示 action、status、potency、owner 等 metadata 覆蓋率。</li><li>[ ] 建立 Action → Status ID 對應。</li><li>[ ] 補齊技能類型：傷害、治療、HoT、盾、Buff、Debuff、減傷。</li><li>[ ] 補齊 GCD／oGCD、冷卻、充能與持續時間。</li><li>[ ] 校準玩家、寵物、召喚物與地面效果 owner 歸屬。</li><li>[ ] 完善 DoT snapshot 與合併 tick 歸屬。</li><li>[ ] 辨識死亡、復活、虛弱與衰弱狀態。</li><li>[ ] 辨識 Boss 不可選取、過場與有效攻擊目標。</li><li>[x] 建立 timeline coverage schema 與穩定事件 ID；Advanced UI 已顯示整體 coverage／diagnostics，並區分 metadata 覆蓋率與技能事件是否存在。</li><li>[x] 每項 evidence finding 保存支持它的事件 ID／時間點，並可由 UI 跳回 Timeline。</li></ul><h3 id="驗收" tabindex="-1">驗收 <a class="header-anchor" href="#驗收" aria-label="Permalink to &quot;驗收&quot;">​</a></h3><ul><li>隨機抽查技能時間軸，施放者、目標、技能與狀態沒有明顯漏記或重複。</li><li>使用者能展開任一建議，看到它依據哪些事件及為何成立。</li><li>metadata 不足的分析會降級或停止，不用預設值假裝精準。</li></ul><h2 id="第二階段-死亡回放" tabindex="-1">第二階段：死亡回放 <a class="header-anchor" href="#第二階段-死亡回放" aria-label="Permalink to &quot;第二階段：死亡回放&quot;">​</a></h2><ul><li>[x] 每次死亡擷取前 15 秒的承傷與治療事件。</li><li>[ ] 顯示死亡前 HP 變化。</li><li>[x] 顯示受到的傷害、來源與技能。</li><li>[x] 顯示收到的有效治療與 overheal。</li><li>[ ] 顯示實際使用掉的護盾。</li><li>[ ] 顯示當時有效的個人／團隊減傷。</li><li>[ ] 顯示易傷、虛弱及其他危險 Debuff。</li><li>[ ] 區分單次致死、連續傷害、缺治療、機制失敗與 overkill。</li><li>[ ] 顯示可能缺少、過早或過晚的防護技能。</li><li>[ ] 支援成功把相同機制時間點對照。</li></ul><h3 id="驗收-1" tabindex="-1">驗收 <a class="header-anchor" href="#驗收-1" aria-label="Permalink to &quot;驗收&quot;">​</a></h3><p>死亡卡片能回答：誰在何時被什麼打死、當時有什麼防護、前 15 秒發生什麼，以及哪些內容因資料不足 無法判定。</p><h2 id="第三階段-成功把與失敗把比較" tabindex="-1">第三階段：成功把與失敗把比較 <a class="header-anchor" href="#第三階段-成功把與失敗把比較" aria-label="Permalink to &quot;第三階段：成功把與失敗把比較&quot;">​</a></h2><ul><li>[ ] 允許指定一把成功紀錄為基準。</li><li>[ ] 依 Boss 技能、階段或人工錨點對齊兩把時間軸。</li><li>[ ] 比較相同機制時的 Boss HP 與團隊 HP。</li><li>[ ] 比較死亡、復活、易傷與失誤 Debuff。</li><li>[ ] 比較每位玩家 GCD 數與長空窗。</li><li>[ ] 比較爆發技能與團隊 Buff 漂移。</li><li>[ ] 比較團隊減傷、護盾與治療技能。</li><li>[ ] 標示技能早開、晚開、漏開及未覆蓋傷害。</li><li>[ ] 分離死亡造成的損失與存活期間的操作差異。</li><li>[ ] 依影響程度列出最重要的差異，不只列全部差異。</li></ul><h3 id="驗收-2" tabindex="-1">驗收 <a class="header-anchor" href="#驗收-2" aria-label="Permalink to &quot;驗收&quot;">​</a></h3><p>每個失敗 pull 都能產出「相較成功把最重要的差異」，並可跳到兩把對應的時間點核查。</p><h2 id="第四階段-團隊減傷與治療計畫" tabindex="-1">第四階段：團隊減傷與治療計畫 <a class="header-anchor" href="#第四階段-團隊減傷與治療計畫" aria-label="Permalink to &quot;第四階段：團隊減傷與治療計畫&quot;">​</a></h2><ul><li>[ ] 允許手動建立機制與時間錨點。</li><li>[ ] 允許為機制配置預定技能與負責玩家。</li><li>[ ] 支援從成功把建立計畫範本。</li><li>[ ] 顯示技能是否實際使用。</li><li>[ ] 計算實際使用相對計畫提早或延後的秒數。</li><li>[ ] 判斷技能是否實際覆蓋傷害事件。</li><li>[ ] 顯示同類技能重疊與覆蓋空窗。</li><li>[ ] 顯示下一個機制前冷卻是否可用。</li><li>[ ] 顯示當時可用但未使用的技能；證據不足時不下結論。</li><li>[ ] 依 pull 計算計畫達成狀態，不建立模糊總分。</li></ul><h3 id="驗收-3" tabindex="-1">驗收 <a class="header-anchor" href="#驗收-3" aria-label="Permalink to &quot;驗收&quot;">​</a></h3><p>每個重要團傷都能顯示計畫、實際使用、覆蓋結果與差異。</p><h2 id="第五階段-通用個人操作分析" tabindex="-1">第五階段：通用個人操作分析 <a class="header-anchor" href="#第五階段-通用個人操作分析" aria-label="Permalink to &quot;第五階段：通用個人操作分析&quot;">​</a></h2><p>目前已完成保守第一版：GCD 空窗會排除死亡，但 encounter targetability 未知時只列中性觀測；冷卻分析只比較實際使用間隔，不推定漏用、充能或資源。</p><ul><li>[ ] 找出長 GCD 空窗，排除死亡、過場與 Boss 不可選取時間。</li><li>[ ] 顯示空窗發生在哪個機制。</li><li>[ ] 比較主要冷卻技能理論與實際使用次數。</li><li>[ ] 偵測冷卻技能長時間未使用。</li><li>[ ] 偵測充能技能溢出。</li><li>[ ] 顯示兩分鐘爆發漂移。</li><li>[ ] 顯示 Buff 視窗內的實際技能序列。</li><li>[ ] 顯示 DoT 中斷與重新施放時間。</li><li>[ ] 偵測攻擊錯誤目標或無效目標。</li><li>[ ] 比較成功把與失敗把的個人操作差異。</li></ul><h3 id="驗收-4" tabindex="-1">驗收 <a class="header-anchor" href="#驗收-4" aria-label="Permalink to &quot;驗收&quot;">​</a></h3><p>建議必須是可行動且可核查的描述，例如「第 242 秒後有 4.8 秒 GCD 空窗」，不能只顯示低於固定分數。</p><h2 id="第六階段-職業專屬分析" tabindex="-1">第六階段：職業專屬分析 <a class="header-anchor" href="#第六階段-職業專屬分析" aria-label="Permalink to &quot;第六階段：職業專屬分析&quot;">​</a></h2><p>目前已完成版本鎖定的龍騎士第一版：支援 <code>2026.07.22.0000.0000</code> 的 DoT、連段、proc 與 buff-window action sequence；未知 build 會停用規則。量譜、身位、充能與更多職業仍未完成。</p><p>優先支援團隊實際使用的職業，不要求一次完成全部職業：</p><ul><li>[ ] 主要資源與量譜。</li><li>[ ] 連段順序。</li><li>[ ] 關鍵 Buff 與爆發週期。</li><li>[ ] 充能、資源上限與溢出。</li><li>[ ] DoT／HoT 維持規則。</li><li>[ ] 特殊技能條件與技能變體。</li><li>[ ] 移動期間可用技能。</li><li>[x] 龍騎士第一版具備遊戲版本與規則版本鎖定。</li><li>[x] 龍騎士第一版每條 finding 具備資料來源、可信度與事件證據。</li></ul><h3 id="驗收-5" tabindex="-1">驗收 <a class="header-anchor" href="#驗收-5" aria-label="Permalink to &quot;驗收&quot;">​</a></h3><p>職業建議來自實際職業機制與事件，不再只依賴 GCD uptime 或 Buff action density。</p><h2 id="第七階段-encounter-與機制資料" tabindex="-1">第七階段：Encounter 與機制資料 <a class="header-anchor" href="#第七階段-encounter-與機制資料" aria-label="Permalink to &quot;第七階段：Encounter 與機制資料&quot;">​</a></h2><ul><li>[ ] 建立 encounter metadata 格式與版本。</li><li>[ ] Boss 技能 ID 與機制名稱。</li><li>[ ] 階段切換條件。</li><li>[ ] 團傷、死刑、分攤與連續傷害分類。</li><li>[ ] Boss 不可選取區間。</li><li>[ ] Add、物件與有效攻擊目標。</li><li>[ ] 機制失敗 Debuff。</li><li>[ ] 擊退、強制移動與站位機制。</li><li>[ ] 成功、失敗與 wipe 判定。</li><li>[ ] 允許人工修正及自訂名稱。</li></ul><h3 id="驗收-6" tabindex="-1">驗收 <a class="header-anchor" href="#驗收-6" aria-label="Permalink to &quot;驗收&quot;">​</a></h3><p>時間軸能以實際機制和階段分段，而不只顯示技能 ID 或大型目標名稱。</p><h2 id="第八階段-介面與輸出" tabindex="-1">第八階段：介面與輸出 <a class="header-anchor" href="#第八階段-介面與輸出" aria-label="Permalink to &quot;第八階段：介面與輸出&quot;">​</a></h2><ul><li>[ ] 首頁顯示本把最重要的三項發現。</li><li>[ ] 分成死亡、團隊、個人與資料限制。</li><li>[x] 目前 evidence findings 可跳到時間軸。</li><li>[ ] 成功把與失敗把可並排比較。</li><li>[x] evidence findings 顯示證據與可信度，不使用模糊總分。</li><li>[ ] 支援忽略不適用的建議。</li><li>[ ] 支援團隊註記與人工機制錨點。</li><li>[ ] 匯出簡潔的檢討摘要。</li><li>[ ] 保存並重用團隊技能計畫。</li></ul><h2 id="最小可用版本" tabindex="-1">最小可用版本 <a class="header-anchor" href="#最小可用版本" aria-label="Permalink to &quot;最小可用版本&quot;">​</a></h2><p>工作規格 02 第一個真正可用的交付，不需要等待所有職業專屬規則完成，但至少包含：</p><ul><li>死亡前 15 秒回放。</li><li>指定成功把並比較相同機制。</li><li>團隊減傷／治療計畫與實際使用比較。</li><li>可跳到時間軸的具體建議。</li><li>每項結論的證據、公式口徑與可信度。</li></ul><p>完成這組功能後，進階分析才從 baseline 統計頁進入可實際協助開荒檢討的階段。</p><h2 id="明確不先做的項目" tabindex="-1">明確不先做的項目 <a class="header-anchor" href="#明確不先做的項目" aria-label="Permalink to &quot;明確不先做的項目&quot;">​</a></h2><ul><li>不在 FFLogs 對帳完成前用未校準數字建立職業評分。</li><li>不先建立單一「總分」或玩家排名。</li><li>不用固定 overheal 門檻直接判定補師操作錯誤。</li><li>不用固定 GCD uptime 門檻忽略機制與不可選取時間。</li><li>不一次支援所有 encounter 與所有職業。</li><li>不把推估值包裝成 log 直接提供的事實。</li></ul>',59)])])}const b=i(r,[["render",t]]);export{f as __pageData,b as default};
